<?php require_once __DIR__ . '/../includes/auth.php'; require_login(); require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; $rows=$conn->query("SELECT d.name department_name, wr.status, COUNT(*) total_records FROM work_records wr INNER JOIN employees e ON wr.employee_id=e.id INNER JOIN departments d ON e.department_id=d.id GROUP BY d.name, wr.status ORDER BY d.name, wr.status"); include __DIR__ . '/../includes/header.php'; include __DIR__ . '/../includes/navbar.php'; ?>
<div class="container py-4"><h2 class="page-title mb-3">Attendance Report - JOIN Operation</h2><div class="card shadow-sm"><div class="card-body"><p class="text-muted">This report uses JOIN between work_records, employees and departments.</p><table class="table"><thead><tr><th>Department</th><th>Status</th><th>Total</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()): ?><tr><td><?php echo e($r['department_name']); ?></td><td><?php echo e($r['status']); ?></td><td><?php echo e($r['total_records']); ?></td></tr><?php endwhile; ?></tbody></table></div></div></div><?php include __DIR__ . '/../includes/footer.php'; ?>
